import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useNavigate, useLocation } from 'react-router-dom';
import {
    Card,
    Stack,
    Button,
    Popover,
    MenuItem,
    Typography,
    IconButton,
    TablePagination,
    Box,
    Dialog,
    DialogTitle,
    DialogContent,
    DialogActions,
    TextField
} from '@mui/material';
import AddBoxIcon from '@mui/icons-material/AddBox';
import { axios } from '../../utils/axios';
import { updateUrlParams } from '../../utils/urlUtilis';
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
import { UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import useResponsive from '../../hooks/useResponsive';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import DateFormat from '../../components/dayjsFormat/DateFormat';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

const ViewAdminReplies = () => {
    const location = useLocation();
    const queryParams = new URLSearchParams(location.search);
    const reviewIds = queryParams.get('reviewIds') || null;
    const navigate = useNavigate();
    const { i18 } = useMyContext();
    const [reviewList, setReviewList] = useState([]);
    const [replyList, setReplyList] = useState([]);
    const [opensDeleteModal, setOpensDeleteModal] = useState(false);
    const [totalCount, setTotalCount] = useState(0);
    const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
    const [search, setsearch] = useState(queryParams.get('search') || '');
    const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
    const [replyModalOpen, setReplyModalOpen] = useState(false);
    const [replyEdit, setReplyEdit] = useState('');
    const [bookingIdEdit, setBookingIdEdit] = useState('');
    const [listingIdEdit, setListingIdEdit] = useState('');
    const [reviewIdEdit, setReviewIdEdit] = useState('');
    const [filters, setFilters] = useState({ });
    const [isLoading, setIsLoading] = useState(true);

    const isMobile = useResponsive('down', 'sm')

    const fetchData = async () => {
        setIsLoading(true);
        try {
            // let url = `module/gallery/images?collection=listings?_page=${page}&_limit=${rowsPerPage}`
            let url = `module/admin/reviews?_page=${page}&_limit=${rowsPerPage}&reviewId=${reviewIds}`

            // if (search) {
            //     url += `&search=${search}`;
            //     setPage(1);
            // }
            if (search) url += `&search=${search}`;
            Object.entries(filters).forEach(([key, value]) => {
                if (value) url += `&${key}=${value}`;
            });
            const response = await axios.get(url);
            if (response.status === 200) {
                setReviewList(response?.data?.data?.reviewAndRating[0]);
                setReplyList(response?.data?.data?.reviewAndRating[0]?.reply)
                setTotalCount(response?.data?.totalCount ? response?.data?.totalCount : 0);
            }
        } catch (error) {
            console.error(error);
        } finally {
            setIsLoading(false);
        }
    }

    useEffect(() => {
        fetchData();
    }, [page, rowsPerPage, search, filters]);

    useEffect(() => {
        updateUrlParams({ page, limit: rowsPerPage });
    }, [page, rowsPerPage, search]);

    const handleChangePage = (event, newPage) => {
        setPage(newPage + 1);
    };

    const handleChangeRowsPerPage = (event) => {
        const newLimit = parseInt(event.target.value, 10);
        setRowsPerPage(newLimit);
        setPage(1);
    };

    const handleFilterByName = (event) => {
        const filterValue = event.target.value;
        setsearch(filterValue);
        queryParams.set('search', filterValue);
        window.history.pushState(null, '', `?${queryParams.toString()}`);
    };

    const handleformdata = (bookingId, listingId, reviewId) => {
        setBookingIdEdit(bookingId);
        setListingIdEdit(listingId);
        setReviewIdEdit(reviewId);
        setReplyModalOpen(true);
    };
    const ActionComponent = (cell) => {
        const value = cell?.getValue();
        const [anchorEl, setAnchorEl] = useState(null);
        const [menuRowId, setMenuRowId] = useState(null);

        const handleActionMenu = (event, rowId) => {
            setAnchorEl(event.currentTarget);
            setMenuRowId(rowId);
        };

        const handleActionMenuClose = () => {
            setAnchorEl(null);
            setMenuRowId(null);
        };

       

        const deleteModal = (ids, reviewId, replyId) => {
            sessionStorage.setItem('rowListingIds', ids);
            sessionStorage.setItem('rowReviewIds', reviewId);
            sessionStorage.setItem('rowReplyIds', replyId)
            setOpensDeleteModal(true);
        };

        return (
            <>
                <IconButton
                    sx={{
                        width: '37px',
                        height: '37px',
                        background: '#EBEBEB',
                        color: 'black',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        borderRadius: '50%',
                    }}
                    onClick={(event) => handleActionMenu(event, value)}
                >
                    <Iconify icon="mdi:dots-horizontal" />
                </IconButton>
                <Popover
                    anchorEl={anchorEl}
                    open={Boolean(anchorEl) && menuRowId === value}
                    onClose={handleActionMenuClose}
                    anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
                    transformOrigin={{ vertical: 'top', horizontal: 'right' }}
                    PaperProps={{
                        sx: { width: 140 },
                    }}
                >
                    {/* <MenuItem onClick={() => handleformdata(original?.listingId, original?.bookingId, original?.reviewId)}>
                        <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
                    </MenuItem> */}
                    <MenuItem onClick={() => deleteModal(reviewList?._id, reviewList?.reviewId, value)} sx={{ color: 'error.main' }}>
                        <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
                    </MenuItem>
                </Popover>
            </>
        )
    }

    const columns = [
        {
            header: i18?.ACCOUNTSTITLE?.REPLIERSNAME || "Replier's Name",
            id: "replierName",
            accessorKey: "replierName",
            showFilter: false, 
        },
        {
            header: i18?.ACCOUNTSTITLE?.ADMINREPLY || "Replies",
            id: "response",
            accessorKey: "response"
        },
        {
            header: i18?.ACCOUNTSTITLE?.REPLIEDAT || "Replied At",
            id: "dateOfReply",
            accessorKey: "dateOfReply",
            cell: ({ row }) => (
                <span>{DateFormat(row?.original?.dateOfReply)}</span>
            ),
        },
        {
            header: i18?.ACCOUNTSTITLE?.ACTION || "Action",
            id: "action",
            accessorKey: "replyId",
            cell: ActionComponent,
        }
    ];

    // const columns = useMemo(() => COLUMNS, []);
    // const data = useMemo(() => {
    //     if (!replyList.length) return [];
    //     return replyList.map((reply) => ({
    //         replierName: reply?.replierName,
    //         response: reply.response,
    //         dateOfReply: reply.dateOfReply,
    //         action: reply,
    //         reviewedUserName: reviewList?.reviewedUserName,
    //         review: reviewList?.review,
    //         dateOfReview: reviewList?.dateOfReview,
    //         reviewId: reviewList?.reviewId,
    //         listingId: reviewList?._id,
    //         bookingId: reviewList?.bookingId,
    //     }));
    // }, [replyList, reviewList]);


    const deleteAdminReplies = async () => {
        const listingIds = sessionStorage.getItem('rowListingIds');

        const reviewIds = sessionStorage.getItem('rowReviewIds');

        const replyIds = sessionStorage.getItem('rowReplyIds');

        try {
            const res = await axios.delete(`module/admin/reviews?listingId=${listingIds}&reviewId=${reviewIds}&replyId=${replyIds}`);
            if (res.status === 200) {
                GenerateToastConfig(res.data.message, 'info');
                setOpensDeleteModal(false);
                fetchData();
            } else {
                GenerateToastConfig(res?.data?.message);
            }
        } catch (error) {
            GenerateToastConfig(error?.response?.data?.message);
        }
    };

    const backToRoute = () => {
        navigate('/dashboard/reviewManagement')
    }

    const handleReplyModalClose = () => {
        setReplyModalOpen(false)
        setReplyEdit('');
    }

    const handleReplyChange = async (bookingId, listingId, reviewId) => {
        try {
            const urlencoded = new URLSearchParams();
            urlencoded.append("response", replyEdit);
            urlencoded.append("reviewId", reviewId);
            urlencoded.append("type", "admin");

            const response = await axios.post(`module/listing/reviewsAndRating/${bookingId}/${listingId}`, urlencoded);
            if (response?.status === 200) {
                GenerateToastConfig(response?.data?.message, 'success');
                setReplyModalOpen(false)
                fetchData();
            }

        } catch (error) {
            console.error(error.message);
        }
    }

    const handleFilterChange = (filterKey, value) => {
        setFilters((prev) => ({ ...prev, [filterKey]: value }));
        setPage(1);
      };

    return (
        <>
            <Helmet>
                <title> View Replies | Admin panel </title>
            </Helmet>
            {isMobile && <Stack direction='row' alignItems="center" style={{ marginBottom: "30px" }} justifyContent="space-between">
                <Typography variant="h4" gutterBottom>
                    {i18?.ACCOUNTSTITLE?.ADMINREPLY || "Replies"}
                </Typography>
                <Button sx={{
                    padding: "9px 28px"
                }} variant="contained" onClick={() => handleformdata(reviewList?._id, reviewList?.bookingId, reviewList?.reviewId,)} startIcon={<AddBoxIcon />}>
                    {i18?.ACCOUNTSTITLE?.ADD_REPLY || "Add Reply"}
                </Button>
            </Stack>}
            {!isMobile && <Stack direction='row' alignItems="center" justifyContent="space-between">
                <Stack direction={'row'} alignItems="center" >
                    <Box
                        sx={{
                            width: '37px',
                            height: '37px',
                            background: '#FF5A60',
                            display: 'flex',
                            alignItems: 'center',
                            justifyContent: 'center',
                            borderRadius: '50%',
                            cursor: 'pointer',
                            marginRight: '10px',
                            marginBottom: '8px',
                        }}
                        onClick={backToRoute}
                    >
                        <Iconify icon={'mdi:arrow-left'} width={24} height={24} color="white" />
                    </Box>
                    <Typography variant="h4" gutterBottom>
                        {i18?.ACCOUNTSTITLE?.ADMINREPLY || "Replies"}
                    </Typography>
                </Stack>
                <Stack direction='row' alignItems="center" >
                    <UserListToolbar
                        // numSelected={selected.length}
                        // filterName={filterName}
                        onFilterName={handleFilterByName}
                        search={search}
                        setsearch={setsearch}
                    />
                    <Button sx={{
                        padding: "9px 28px"
                    }} variant="contained" onClick={() => handleformdata(reviewList?._id, reviewList?.bookingId, reviewList?.reviewId,)} startIcon={<AddBoxIcon />}>
                        {i18?.ACCOUNTSTITLE?.ADD_REPLY || "Add Reply"}
                    </Button>
                </Stack>
            </Stack>}

            <Card sx={{ padding: '0px 0px', margin: '0px 0px', overflowX: 'auto' }}>
                {isMobile && <UserListToolbar
                    // numSelected={selected.length}
                    // filterName={filterName}
                    onFilterName={handleFilterByName}
                    search={search}
                    setsearch={setsearch}
                />}

                <Scrollbar>
                    {/* <TanstackTable data={data} columns={columns} /> */}
                    <TanstackTableV8
                        data={replyList}
                        columns={columns}
                        filters={filters}
                        isLoading={isLoading}
                        onFilterChange={handleFilterChange}
                    />
                </Scrollbar>
            </Card>

            <TablePagination
                rowsPerPageOptions={[5, 10, 25]}
                component="div"
                count={totalCount || 0}
                rowsPerPage={rowsPerPage}
                page={page - 1}
                onPageChange={handleChangePage}
                onRowsPerPageChange={handleChangeRowsPerPage}
                sx={{
                    '.MuiTablePagination-selectLabel': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-displayedRows': {
                        marginTop: '12px',
                    },
                    '.MuiTablePagination-actions': {
                        marginBottom: '6px',
                    }
                }}
            />

            <DeleteModal
                isDeleteOpen={opensDeleteModal}
                handleClose={() => setOpensDeleteModal(false)}
                handleDelete={deleteAdminReplies}
            />

            <Dialog
                open={replyModalOpen}
                onClose={handleReplyModalClose}
                maxWidth='xs'
                fullWidth
            >
                <DialogTitle>Edit Reply</DialogTitle>
                <DialogContent>
                    {/* <TextField 
                        autoFocus
                        margin="dense"
                        id="review"
                        label="Review"
                        type="text"
                        fullWidth
                        variant="standard"
                        value={reviewList?.review}
                    /> */}
                    <TextField
                        autoFocus
                        margin='dense'
                        id='reply'
                        label='Reply'
                        type='text'
                        fullWidth
                        variant='standard'
                        value={replyEdit}
                        onChange={(e) => setReplyEdit(e.target.value)}
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleReplyModalClose}>Cancel</Button>
                    <Button disabled={!replyEdit} onClick={() => handleReplyChange(bookingIdEdit, listingIdEdit, reviewIdEdit)}>Submit</Button>
                </DialogActions>
            </Dialog>
        </>
    )
}

export default ViewAdminReplies
